                finally:
                    os.close(descriptor)
            finally:
                self._release_os_lock(lock_handle)

    async def _acquire_os_lock(self, path: Path):
        handle = path.open('a+b')
        try:
            handle.seek(0, os.SEEK_END)
            if handle.tell() == 0:
                handle.write(b'\x00')
                handle.flush()
