class JsonlSessionStore:
    """A bounded, session-keyed transcript store with one-writer appends.

    Each exchange is encoded as one JSON object and appended while holding an
    in-process lock plus an OS advisory lock.  A crash can therefore leave at
    most one incomplete line; readers ignore malformed/oversized lines.

    Session filenames are SHA-256 keys rather than user-controlled paths.  The
    class intentionally exposes no method that enumerates actors or sessions.
    """

    def __init__(self, config: JsonlSessionStoreConfig) -> None:
        self._config = config
        self._root = Path(config.root).expanduser().absolute()
        self._writer_lock = asyncio.Lock()

    @staticmethod
    def _validate_key_part(name: str, value: str) -> None:
        if not isinstance(value, str) or not value:
            raise ValueError(f'{name} must be a non-empty string')
        if '\x00' in value:
            raise ValueError(f'{name} cannot contain NUL')

    def _session_path(self, *, actor_id: str, session_id: str) -> Path:
        self._validate_key_part('actor_id', actor_id)
        self._validate_key_part('session_id', session_id)
        identity = f'{len(actor_id)}:{actor_id}\x00{session_id}'.encode('utf-8')
        digest = hashlib.sha256(identity).hexdigest()
        return self._root / f'{digest}.jsonl'

    async def load(self, *, actor_id: str, session_id: str) -> Sequence[ChatMessage]:
        """Read only the newest configured number of valid messages."""
        path = self._session_path(actor_id=actor_id, session_id=session_id)
        newest: deque[ChatMessage] = deque(maxlen=self._config.max_history_messages)
        try:
            stream = path.open('rb')
        except FileNotFoundError:
            return ()
        try:
            with stream:
                for raw_line in stream:
                    if len(raw_line) > self._config.max_line_bytes:
                        continue
                    try:
                        row = json.loads(raw_line.decode('utf-8'))
                    except (UnicodeDecodeError, json.JSONDecodeError, TypeError):
                        continue
                    if not self._valid_exchange(row, actor_id=actor_id, session_id=session_id):
                        continue
                    newest.append(ChatMessage(role='user', content=row['user']))
                    newest.append(ChatMessage(role='assistant', content=row['assistant']))
        except OSError:
            return ()
        return tuple(newest)

    @staticmethod
    def _valid_exchange(row: object, *, actor_id: str, session_id: str) -> bool:
        return bool(isinstance(row, dict) and row.get('schema') == _EXCHANGE_SCHEMA and (row.get('actor_id') == actor_id) and (row.get('session_id') == session_id) and isinstance(row.get('request_id'), str) and isinstance(row.get('user'), str) and isinstance(row.get('assistant'), str))

    async def append_exchange(self, *, request: ChatRequest, result: ChatResult) -> None:
        """Append one complete exchange under an inter-process writer lock."""
        if request.session_id != result.session_id:
            raise ValueError('request/result session_id mismatch')
        if request.request_id != result.request_id:
            raise ValueError('request/result request_id mismatch')
        path = self._session_path(actor_id=request.actor_id, session_id=request.session_id)
        status = getattr(result.status, 'value', result.status)
        channel = getattr(request.channel, 'value', request.channel)
        row = {'schema': _EXCHANGE_SCHEMA, 'at': datetime.now(timezone.utc).isoformat(timespec='seconds'), 'actor_id': request.actor_id, 'session_id': request.session_id, 'request_id': request.request_id, 'channel': str(channel), 'status': str(status), 'latency_ms': int(result.latency_ms), 'stage': str(getattr(result, 'stage', '') or ''), 'used_web': bool(result.used_web), 'user': request.text, 'assistant': result.text}
        encoded = (json.dumps(row, ensure_ascii=False, separators=(',', ':')) + '\n').encode('utf-8')
        if len(encoded) > self._config.max_line_bytes:
            raise ValueError('exchange exceeds max_line_bytes')
        async with self._writer_lock:
            self._root.mkdir(parents=True, exist_ok=True)
            lock_handle = await self._acquire_os_lock(path.with_suffix('.lock'))
            try:
                descriptor = os.open(path, os.O_APPEND | os.O_CREAT | os.O_WRONLY, 384)
                try:
                    view = memoryview(encoded)
                    while view:
                        written = os.write(descriptor, view)
                        if written <= 0:
                            raise OSError('zero-byte transcript write')
                        view = view[written:]
                    os.fsync(descriptor)
                finally:
                    os.close(descriptor)
            finally:
                self._release_os_lock(lock_handle)

    async def _acquire_os_lock(self, path: Path):
        handle = path.open('a+b')
        try:
            handle.seek(0, os.SEEK_END)
            if handle.tell() == 0:
                handle.write(b'\x00')
                handle.flush()
            deadline = monotonic() + self._config.lock_timeout_s
            while True:
                handle.seek(0)
                try:
                    if os.name == 'nt':
                        import msvcrt
                        msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                    else:
                        import fcntl
                        fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                    return handle
                except (BlockingIOError, OSError):
                    if monotonic() >= deadline:
                        raise SessionStoreBusyError('transcript writer lock timed out')
                    await asyncio.sleep(0.01)
        except BaseException:
            handle.close()
            raise

    @staticmethod
    def _release_os_lock(handle) -> None:
        try:
            handle.seek(0)
            if os.name == 'nt':
                import msvcrt
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
        finally:
            handle.close()

