        if len(encoded) > self._config.max_line_bytes:
            raise ValueError('exchange exceeds max_line_bytes')
        async with self._writer_lock:
            self._root.mkdir(parents=True, exist_ok=True)
            lock_handle = await self._acquire_os_lock(path.with_suffix('.lock'))
            try:
                descriptor = os.open(path, os.O_APPEND | os.O_CREAT | os.O_WRONLY, 384)
                try:
                    view = memoryview(encoded)
                    while view:
                        written = os.write(descriptor, view)
                        if written <= 0:
                            raise OSError('zero-byte transcript write')
                        view = view[written:]
                    os.fsync(descriptor)
                finally:
                    os.close(descriptor)
            finally:
                self._release_os_lock(lock_handle)

    async def _acquire_os_lock(self, path: Path):
        handle = path.open('a+b')
        try:
            handle.seek(0, os.SEEK_END)
            if handle.tell() == 0:
                handle.write(b'\x00')
                handle.flush()
            deadline = monotonic() + self._config.lock_timeout_s
            while True:
                handle.seek(0)
                try:
                    if os.name == 'nt':
                        import msvcrt
                        msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                    else:
                        import fcntl
                        fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                    return handle
                except (BlockingIOError, OSError):
                    if monotonic() >= deadline:
                        raise SessionStoreBusyError('transcript writer lock timed out')
                    await asyncio.sleep(0.01)
        except BaseException:
            handle.close()
            raise

    @staticmethod
    def _release_os_lock(handle) -> None:
        try:
            handle.seek(0)
            if os.name == 'nt':
                import msvcrt
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
        finally:
            handle.close()

